INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('miss-kobayashi-s-dragon-maid-s','Miss Kobayashi''s Dragon Maid S','小林さんちのメイドラゴンＳ',2021,8.2,'Summer 2021','TV','Finished','https://media.kitsu.app/anime/poster_images/42149/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/107717-xi8BDn9kucOI.jpg','#ff9420','A strange turn of events leads the Dragon, Tohru, to work as Miss Kobayashi''s maid. She occasionally (that''s a lie, she often) causes trouble for her beloved Miss Kobayashi while blending into human society and splendidly (that''s a lie, only mediocrely) carrying out her maid duties. Her fellow dragons, Kanna, Lucoa, Fafnir, and Elma all find their own places to fit in as well and enjoy interspecies interactions with the humans. Yet while they''re all enjoying that laid-back and occasionally turbulent left, the threat of a new Dragon swoops down upon Miss Kobayashi. (Source: Crunchyroll)',NULL,'["Miss Kobayashi''s Dragon Maid: Valentines and Hot Springs! (Please Don''t Get Your Hopes Up) (2017)","Miss Kobayashi’s Dragon Maid S: Japanese Hospitality (The Attendant Is a Dragon) (2022)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":42149,"anilist":107717,"mal":39247}',39247,'mal',12,datetime('now'),'miss kobayashi s dragon maid s 小林さんちのメイト ラコ ンs tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('nisekoi','Nisekoi:','ニセコイ：',2015,7.4,'Spring 2015','TV','Finished','https://media.kitsu.app/anime/poster_images/9178/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20876-qnldLnf8ZTrT.jpg','#ff9420','Despite having seemingly quelled the war between their respective gangs, Raku Ichijou and Chitoge Kirisaki still carry on with their fake relationship. Eventually, as Chitoge''s perception of Raku slowly changes, she even begins to see him as a little charming. Chitoge struggles to come to terms with her newfound feelings for Raku, as a new girl joins the slew of Raku''s admirers and the competition among those vying for the yakuza heir''s attention grows even fiercer. And amidst all this, Raku''s search for his first love and the contents of the mysterious sealed locket continues in Nisekoi:, which picks up where the first season left off. [Written by MAL Rewrite]',NULL,'["Nisekoi (2014)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":9178,"anilist":20876,"mal":27787}',27787,'mal',12,datetime('now'),'nisekoi ニセコイ tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('amagi-brilliant-park','Amagi Brilliant Park','甘城ブリリアントパーク',2014,7.5,'Fall 2014','TV','Finished','https://media.kitsu.app/anime/poster_images/8259/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20602-HrakjBfgWeRg.jpg','#ff9420','A mysterious but pretty transfer student, Sento Isuzu, asks Kanie Seiya out on a date to an amusement park. That park was Amagi Brilliant Park, featuring worn-down attractions and lackluster service -- the worst in Japan. (Source: Crunchyroll)',NULL,'["Amagi Brilliant Park: No Time to Take It Easy! (2015)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":8259,"anilist":20602,"mal":22147}',22147,'mal',13,datetime('now'),'amagi brilliant park 甘城フ リリアントハ ーク tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('btooom','BTOOOM!','BTOOOM！',2012,7.3,'Fall 2012','TV','Finished','https://media.kitsu.app/anime/poster_images/7113/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/14345-e2mFB7Z21V8s.jpg','#a24bff','Ryouta Sakamoto is unemployed and lives with his mother, his only real achievement being that he is Japan''s top player of the popular online video game, "Btooom!" However, his peaceful life is about to change when he finds himself stranded on an island in the middle of nowhere, with a small, green crystal embedded in his left hand and no memory of how he got there. To his shock, someone has decided to recreate the game he is so fond of in real life, with the stakes being life or death. Armed with a bag full of unique bombs known as "BIM," the players are tasked with killing seven of their fellow participants to obtain their green crystals, used as proof of their victory, in order to return home. Initially condemning any form of violence, Ryouta is forced to fight when he realizes that many of the other players are not as welcoming as they may seem. Teaming up with Himiko, a fellow Btooom! player who turns out to be his in-game wife, they attempt to get off of the island together, slowly coming closer and closer to the truth behind this contest of death. [Written by MAL Rewrite]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":7113,"anilist":14345,"mal":14345}',14345,'anilist',12,datetime('now'),'btooom btooom tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('akudama-drive','Akudama Drive','アクダマドライブ',2020,7.6,'Fall 2020','TV','Finished','https://media.kitsu.app/anime/43067/poster_image/medium-22d6ab813c379c84bdf5b5c1dc13491b.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/116566-XwsHAwTxbXmC.jpg','#ffc247','Many years ago, a Great Civil War ravaged Japan, leaving the country fragmented between two regions: Kansai and Kanto. In Kansai, a group of six Akudama carry out missions given to them by a mysterious black cat, while evading the police. But a dangerous journey is about to unfold when a civilian girl becomes twisted into the Akudama’s way of life and witnesses their criminal drives. (Source: Funimation)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":43067,"anilist":116566,"mal":41433}',41433,'mal',12,datetime('now'),'akudama drive アクタ マト ライフ tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('sentenced-to-be-a-hero','Sentenced to Be a Hero','勇者刑に処す 懲罰勇者9004隊刑務記録',2026,8.1,'Winter 2026','TV','Finished','https://media.kitsu.app/anime/47759/poster_image/medium-4c38733db38c2b09a87d2b533cc1e49f.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/167152-6QxZG8Dmf1EL.jpg','#2f7bff','In a world where heroism is a punishment, Xylo Forbartz, a condemned goddess killer, battles endless hordes of monstrous abominations as part of Penal Hero Unit 9004. Death is no escape, only a cycle of resurrection and relentless combat. But when Xylo encounters a mysterious new goddess, their unlikely alliance sparks a rebellion that could shatter the chains of eternal punishment. (Source: Crunchyroll) Notes: - The first episode aired with a runtime of ~58 minutes as opposed to the standard 24 minute long episode. - Initially scheduled to air in October, 2025',NULL,'["Sentenced to Be a Hero Season 2"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":47759,"anilist":167152,"mal":56009}',NULL,NULL,12,datetime('now'),'sentenced to be a hero 勇者刑に処す 懲罰勇者9004隊刑務記録 tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
