INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('the-millionaire-detective-balance-unlimited','The Millionaire Detective - Balance: UNLIMITED','富豪刑事 Balance:UNLIMITED',2020,7.8,'Spring 2020','TV','Finished','https://media.kitsu.app/anime/poster_images/43056/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/114888-YVXJvMnuWCDb.jpg','#2f7bff','Detective Daisuke Kanbe has no problems using his own fortune to solve crimes even if he assesses human lives based on their financial worth. Compassionate Haru Katosees all life as sacred and is sickened by Daisuke’s materialistic ways. Can they stop butting heads and overcome their opposing world views for the sake of solving the toughest crimes in the precinct? (Source: Funimation)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":43056,"anilist":114888,"mal":41120}',41120,'mal',11,datetime('now'),'the millionaire detective balance unlimited 富豪刑事 balance unlimited tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('kuroko-s-basketball-3','Kuroko''s Basketball 3','黒子のバスケ 3rd SEASON',2015,8.2,'Winter 2015','TV','Finished','https://media.kitsu.app/anime/8524/poster_image/medium-bfa6b7f06748ce15f23261b7471d2a2e.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20725-ATMoU6GgyT5G.jpg','#ffc247','Following their triumph against Yousen High, Seirin''s basketball team has reached the semifinals of the Winter Cup along with Kaijou, Rakuzan, and Shuutoku. Each of these teams possesses a member of the Generation of Miracles, and Seirin prepares to face the largest obstacles on their path to winning the Winter Cup. In the final season of Kuroko no Basket, Kuroko goes head-to-head with his old teammates once more as he attempts to show them that individual skill is not the only way to play basketball. His firm belief that his form of basketball, team play, is the right way to play the sport will clash with the talents of a perfect copy and an absolute authority. While Kuroko tries to prove that his basketball is "right," he and the rest of Seirin High ultimately have one goal: to win the Winter Cup and overcome the strength of the Generation of Miracles, who have long dominated the scene of middle and high school basketball. [Written by MAL Rewrite]',NULL,'["Kuroko''s Basketball 2 (2013)","Kuroko''s Basketball: Last Game (2017)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":8524,"anilist":20725,"mal":24415}',NULL,NULL,25,datetime('now'),'kuroko s basketball 3 黒子のハ スケ 3rd season tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,s