INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('mieruko-chan','Mieruko-chan','見える子ちゃん',2021,7.5,'Fall 2021','TV','Finished','https://media.kitsu.app/anime/44185/poster_image/medium-15fc19164f4d84fb704f452aaa4ee93e.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/131083-MYE8c1cuzO6C.jpg','#ffc247','All of a sudden, a girl is able to see grotesque monsters all around her; but no one else can. Rather than trying to run away or face them, she instead musters all of her courage and... ignores them. Join her day-to-day life as she keeps up her best poker face despite the supernatural goings-on.',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":44185,"anilist":131083,"mal":48483}',48483,'mal',12,datetime('now'),'mieruko chan 見える子ちゃん tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('the-dangers-in-my-heart','The Dangers in My Heart','僕の心のヤバイやつ',2023,8.2,'Spring 2023','TV','Finished','https://media.kitsu.app/anime/46299/poster_image/medium-6d03c7b6f887ab8dae48e7f52d3a4dfe.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/153152-rBoe4ue4EjzI.jpg','#2ee6a8','Fascinated by murder and all things macabre, Kyoutarou daydreams of acting out his twisted fantasies on his unsuspecting classmates — but an encounter with Anna Yamada, the gorgeous class idol, lights a spark in the darkness of his heart. It’s a classic tale of an antisocial boy falling for a popular girl, but neither are who they appear to be at first glance. Will Kyoutarou and Anna defy their expectations of each other — and of themselves? (Source: HIDIVE)',NULL,'["The Dangers in My Heart Season 2 (2024)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":46299,"anilist":153152,"mal":52578}',52578,'mal',12,datetime('now'),'the dangers in my heart 僕の心のヤハ イやつ tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('the-testament-of-sister-new-devil','The Testament of Sister New Devil','新妹魔王の契約者',2015,6.7,'Winter 2015','TV','Finished','https://media.kitsu.app/anime/poster_images/8652/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/20678-OJNSBFQsH20P.png','#a24bff','Running into your new stepsister in the bathroom is not the best way to make a good first impression, which Basara Toujou learns the hard way. When his father suddenly brings home two beautiful girls and introduces them as his new siblings, he has no choice but to accept into his family the Naruse sisters: busty redhead Mio and petite silver-haired Maria. But when these seemingly normal girls reveal themselves as demons—Mio the former Demon Lord''s only daughter and Maria her trusted succubus servant—Basara is forced to reveal himself as a former member of a clan of "Heroes," sworn enemies of the demons. However, having begun to care for his new sisters, Basara instead decides to protect them with his powers and forms a master-servant contract with Mio to keep watch over her. With the Heroes observing his every move and the constant threat of hostile demons, Basara has to do the impossible to protect his new family members. Moreover, the protector himself is hiding his own dark secret that still haunts him to this day... [Written by MAL Rewrite]',NULL,'["The Testament of Sister New Devil: Tojo Basara''s Hard, Sweet Daily Life (2015)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":8652,"anilist":20678,"mal":23233}',NULL,NULL,12,datetime('now'),'the testament of sister new devil 新妹魔王の契約者 tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,