INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('in-spectre','In/Spectre','虚構推理',2020,7,'Winter 2020','TV','Finished','https://media.kitsu.app/anime/poster_images/42117/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/107201-XZHSg0HdC9kR.jpg','#2f7bff','When she was still just a girl, Kotoko was kidnapped by yokai. These spirits made her into a powerful intermediary between the spirit and human worlds, but this power came at a price: an eye and a leg. Now, years later, she watches out for dangerous yokai while developing feelings for a young man named Kurou, who is also special: an incident with a yokai has given him healing powers. He''s surprised when Kotoko asks him to team up to handle renegade yokai, preserving the thin line between reality and the supernatural. (Source: Kodansha Comic)',NULL,'["In/Spectre 2 (2023)"]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":42117,"anilist":107201,"mal":39017}',39017,'mal',12,datetime('now'),'in spectre 虚構推理 tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text) VALUES ('land-of-the-lustrous','Land of the Lustrous','宝石の国',2017,8.2,'Fall 2017','TV','Finished','https://media.kitsu.app/anime/13521/poster_image/medium-cd960cdafbb58013086e875a7e67b9df.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/98707-ZcFGfUAS4YwK.jpg','#ff1f4a','In the distant future, a new immortal and genderless life form called Gems populate the Earth. The 28 Gems must fight against the Moon Dwellers, who attack them regularly to abduct them and to turn them into decorations. Each Gem is assigned a role, such as a fighter or a medic. Being only 300 years old, Phosphophyllite is the youngest of the Gems and has no assignment yet. They want to help to fight the Moon Dwellers, but is too weak and brittle for battle. One day the master of Gems, Adamantine, assigns them the task of creating a natural history encyclopedia. (Source: MAL News)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":13521,"anilist":98707,"mal":35557}',NULL,NULL,12,datetime('now'),'land of the lustrous 宝石の国 tv finished') ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text;
