INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('nisekoi#12','nisekoi',12,'The Search / Just Testing','24:00',1440,'','Chitoge wants to tell Raku how she feels about him, but she is scared of rejection. Will she manage to gather some courage?','[{"kind":"intro","label":"Opening","start":8,"end":98}]','2015-06-26','170844');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#1','amagi-brilliant-park',1,'Not Enough Visitors!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/149026/original.jpg','Isuzu Sento forces Seiya Kanie, at gun point, to go on a date with her. The location turns out to be Amagi Brilliant Park. While roaming around the place, Isuzu introduces Seiya to the various attractions, and it is very apparent that all of them are very unsatisfactory. After going once over the Park, Isuzu asks Seiya to his thoughts about the place, to which he responds very negatively, finally spouting "You need to believe in a dream yourself for other people to believe in it!". Just when he''s about to leave, Isuzu offers him some croquettes, which turn out to be very delicious. Deciding to know who made them, Seiya follows Isuzu to meet the manager of the Park, Latifah Fullanza. She describes that the Park actors are actually residents from a Magical land, and if they are not able to get enough customers in a determined time, the park will be shut down, and asks Seiya to help by taking over the manager position. She also tells him that she will give him magical powers.','[{"kind":"intro","label":"Opening","start":47,"end":137}]','2014-10-07','149026');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#2','amagi-brilliant-park',2,'Not Enough Time!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/149027/original.jpg','The next day, Seiya realizes he has the power to read people''s mind. Isuzu again takes him to the park, where they proceed to meet some people from Amagi Development - they are the ones who would take over the Park once the time expires. One of them recognized Seiya and tells him not to get close to the losers in the Park, or he too will become one. In the Park, an assembly is held, where the Princess, Latifah Fullanza announces that the Park will be closed in three months. Seiya returns to them and announces that he will save them. But later, when he''s alone with Isuzu and Latifah, he says that he just claimed it to raise everyone''s spirit, but he''s not actually confident about it - but Latifah claims having complete faith in him.','[{"kind":"intro","label":"Opening","start":63,"end":153},{"kind":"outro","label":"Ending","start":1331,"end":1420}]','2014-10-10','149027');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#3','amagi-brilliant-park',3,'Not Enough Reinforcement!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/149028/original.jpg','Seiya makes an announcement for cast workers saying that park will be closed for a day due to repairing. Then he declares three changes: the park will close at 7 p.m., cancel Friday''s day-off and set up a 30 yen payment for all services. When Moffle hits an annoying guest, Isuzu shoots the guest and his family with bullets which causes memory loss. Salama records the fight with her cell phone. Seiya records a promotional video with the Elementario fairies, Latifa and Isuzu wearing swimsuits, but it does not get as many views as expected. Then he uploads an edited video of the fight, which gets many hits, and as a result gave many views to the PV uploaded beforehand.','[{"kind":"intro","label":"Opening","start":24,"end":114}]','2014-10-17','149028');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#4','amagi-brilliant-park',4,'Not Enough PA Productivity!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/149029/original.jpg','Thanks to Seiya''s flawless management, the park''s efficiency and visitor count is increasing, and when informed by Sento that Moffle, Macaron and Tirami have some complains, he decides to let her deal with them instead, but the Elementario Faeries show him that instead of looking for a compromise, Sento just ends the discussion by threatening them with her gun. Seiya then scolds Sento for her behavior, creating a divide between them. In the next day, Latifah asks Seiya to ride the ferris wheel with her and in the occasion, it is revealed that he has a fear of heights, and when conforted by her, Seiya has the feeling that they have met before. Some time later, it starts raining, and with the drainage system broken, threatening to flood the entire park, Sento takes the lead and organizes an emergency operation to prevent further damage. After the rain, Sento reveals that her strict behavior to others is thanks to her military training, and believes that everyone in the park hates her because of that, but Seiya shows her the happy faces of the cast who thank her for her help, proving her wrong.','[{"kind":"intro","label":"Opening","start":48,"end":138},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-10-24','149029');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#5','amagi-brilliant-park',5,'Not Enough Money!','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/149030/original.jpg','The Amagi Brilliant Park has used all its savings and there is no money left to keep it running. However, Moffle remembers about their friend Dornel, who got missing after searching for treasure in an abandoned area of the park, and Seiya, Isuzu, Macaron, Tiramy and Moffle leave to investigate. While facing several traps along the way, Isuzu and Macaron get separated from the others and discover that Dornel was hidden inside the cave all this time, indulging on several hobbies, while Seiya and the others confront Rubrum, the Red Dragon, and learn that Rubrum and the Diggeries, a group of mole-like fairies were running away from a tyrannical empire and given shelter in the park. Back to the surface, Rubrum and the Diggeries ask for a job in the park as well, and Seiya agrees, while all the items Dornel gathered during his absence are sold to pay for the park''s expenses.','[{"kind":"intro","label":"Opening","start":112,"end":202},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-10-31','149030');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#6','amagi-brilliant-park',6,'Not Enough People!','24:00',1440,'','With the park short on staff, Seiya decides to hold a job interview for new workers and Isuzu gets herself in serious trouble when she unwillingly eats a fruit that forces her to always tell her mind, leaving her in fear of revealing her true feelings for him.','[{"kind":"intro","label":"Opening","start":72,"end":162},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-11-07','149031');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#7','amagi-brilliant-park',7,'Not Enough Pool Safety!','24:00',1440,'','The park is on alert when a group of pirates from Maple Land appear to wreak havoc. With Isusu, Latifah, Moffle, Macaron and the Elementario Fairies in their custody, it''s up to Seiya and the others to make a stand against the pirates and rescue them. All of that without having the guests realize that it is not an act.','[{"kind":"intro","label":"Opening","start":131,"end":221},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-11-14','149032');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#8','amagi-brilliant-park',8,'Not Enough Love!','24:00',1440,'','Seiya gets a summer cold but he can''t afford to skip school due to his earlier absences. Sento, Macaron, Tiramie and Moffle wear a realistic suit of his body one person per day and attend school in his stead. On the first day, Isuzu finds a love letter in Kanie''s shoe locker but the sender, Tsuchida Kanae, had only mixed up his locker with someone else. As Sento tells her inspiring words, Kanae ends up developing feelings for Kanie instead. The next two days end up with disgusting incidents due to the mascots'' behavior, while the forth day ends peacefully due to Kanie wearing a suit of a boy to whom Kanae had tried to send the letter originally, Kimura, and lying that all the disgusting acts from ''Kanie'' the days before were meant to drive Kanae back to Kimura by making her hate Kanie.','[{"kind":"intro","label":"Opening","start":37,"end":127},{"kind":"outro","label":"Ending","start":1333,"end":1422}]','2014-11-21','149033');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#9','amagi-brilliant-park',9,'Not Enough Teamwork!','24:00',1440,'','Having not improved at all with their attraction due to their lack of teamwork, the Elementario Fairies are invited for dinner with Latifah and unwittingly activate the castle''s defense system. Trapped inside the castle, the fairies must reinitialize the system from the inside, but to do so, they must pass a series of trials that demand them to work together.','[{"kind":"intro","label":"Opening","start":40,"end":130},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-11-28','149034');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#10','amagi-brilliant-park',10,'Nothing Can Be Done!','24:00',1440,'','Everyone''s doing their best but it seems impossible to reach the goal of 250.000 visitors. Isuzu tells Kanie why Latifah faints so often. It turns out that there''s a Animus-draining curse upon the princess. Amagi Brilliant Park was built to keep Latifah alive. Seiya recalled the meeting with the princess when he was young, but she looked exactly the same then. Moffle told him that the curse not only affects her health, but also resets her memories and physical development every year. With only 10 days left to the deadline, Seiya hears from Triken that he found what he asked him to look for, renewing his hopes.','[{"kind":"intro","label":"Opening","start":110,"end":200},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','2014-12-05','149035');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#11','amagi-brilliant-park',11,'Nothing to Worry About Now!','24:00',1440,'','Seiya''s plan to reach the quota in 10 days involves hosting a soccer match at the park''s stadium. After convincing the local soccer team to play an important match at the park, Seiya informs the cast that for their plan to work, a large unused area of the park grounds must be sold in order to pay for the expenses and solve their financial problems, to which they agree, and then they spend the following days making preparations for the match, while Seiya is still worried, knowing that on the last day, Latifah''s memories will be reset and she will forget about him at all once more. The final day comes at last, and with all the visitors counted and a few hours left to the deadline, Seiya gets in shock upon knowing that they are only 252 visitors short from reaching the goal.','[{"kind":"intro","label":"Opening","start":81,"end":171},{"kind":"outro","label":"Ending","start":1331,"end":1421}]','2014-12-12','149036');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#12','amagi-brilliant-park',12,'Nobody Knows What the Future Holds!','24:00',1440,'','As a last resort, the staff of Amagi Brilliant Park invite all their friends and relatives, reaching the quota in the nick of time. Announcing that it''s his last day as manager, Seiya reveals to the others that a huge shopping mall will be established in the land he previously sold, which will help bring guests to the park. Takaya Kurisu from the Amagi Development, compliments Seiya for the feat, but also mocks him because the issue with Latifah''s condition is yet to be solved, revealing himself as the wizard who cursed her in the first place before fleeing. However, when midnight comes, Seiya and the others discover that the huge quantity of Animus gathered in the last weeks was strong enough to break her free for the curse, much to everyone''s joy. Seiya then bids farewell to the people of the park, but when he returns home, his aunt Aisu Kyūbu remarks how happy he was while working there, thus in the next day, Seiya returns and reassumes his post as the manager of Amagi Brilliant Park, claiming that there is still a lot for him to do.','[{"kind":"intro","label":"Opening","start":43,"end":133},{"kind":"outro","label":"Ending","start":1331,"end":1421}]','2014-12-19','149037');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('amagi-brilliant-park#13','amagi-brilliant-park',13,'Not a Good PV!','24:00',1440,'','Triken takes ideas from the staff to make a promotional video for the park with questionable results.','[{"kind":"intro","label":"Opening","start":126,"end":216},{"kind":"outro","label":"Ending","start":1331,"end":1421}]','2014-12-26','149038');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#1','btooom',1,'Start','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98612/original.jpg','Ryōta Sakamoto is ranked #10 worldwide i Btooom!, an online game where players kill each other with bombs. After a game one day, he mysteriously awakes in a real life version of the game.','[{"kind":"outro","label":"Ending","start":1181,"end":1271}]','2012-10-04','98612');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#2','btooom',2,'The Bloodstained High School Girl','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98613/original.jpg','A typical high school girl, betrayed by her neighbors, a forced player in the game of Btooom!, betrayed by the group she teamed up with. All men are scum.','[{"kind":"intro","label":"Opening","start":88,"end":178},{"kind":"outro","label":"Ending","start":1356,"end":1440}]','2012-10-11','98613');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#3','btooom',3,'Survival','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98614/original.jpg','While chasing after the mysterious girl, Ryota runs into Taira Kiyoshi who helps fill in the blanks in his memory.','[{"kind":"intro","label":"Opening","start":31,"end":121},{"kind":"outro","label":"Ending","start":1275,"end":1365}]','2012-10-18','98614');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#4','btooom',4,'Best in the World','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98615/original.jpg','Kira Kosuke is a disturbed child, but when on the island his true nature can finally come out, unchecked. That is until he faces the best Btooom! player in Japan.','[{"kind":"intro","label":"Opening","start":73,"end":163},{"kind":"outro","label":"Ending","start":1298,"end":1388}]','2012-10-25','98615');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#5','btooom',5,'Attack','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98616/original.jpg','A pantless corpse floats by Taira and Sakamoto while they are eating lunch. When Sakamoto leaves to investigate he finds a gruesome scene and a familiar figure.','[{"kind":"intro","label":"Opening","start":83,"end":173}]','2012-11-01','98616');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#6','btooom',6,'Night of Sacrifice','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98617/original.jpg','In the moment of danger, trust issues start to show between Taira and Sakamoto. Sakamoto wants to save everyone especially the girl who just tried to kill him.','[{"kind":"outro","label":"Ending","start":1314,"end":1404}]','2012-11-08','98617');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#7','btooom',7,'Virtual Bride','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98618/original.jpg','Miyamoto, the mercenary, has found Sakamoto and his team. This dangerous player will do anything it takes to win.','[{"kind":"intro","label":"Opening","start":62,"end":152},{"kind":"outro","label":"Ending","start":1351,"end":1440}]','2012-11-15','98618');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#8','btooom',8,'White Ghost','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98619/original.jpg','As Sakamoto and Himiko try to rest for the night, Himiko wrestles with the idea of telling Sakamoto her true identity, but before she can do anything she is visited by a “ghost”.','[{"kind":"intro","label":"Opening","start":101,"end":191},{"kind":"outro","label":"Ending","start":1295,"end":1386}]','2012-11-22','98619');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#9','btooom',9,'The Strongest Player','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98620/original.jpg','A new player has joined Sakamoto''s team, but he carries a dark secret. Before the team could dive deeper into the new players past, a food drop overhead brings many players out of hiding.','[{"kind":"intro","label":"Opening","start":94,"end":184},{"kind":"outro","label":"Ending","start":1356,"end":1440}]','2012-11-29','98620');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#10','btooom',10,'High Level','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98621/original.jpg','It seems the players on the island are interconnected in more ways than one. While Sakamoto mulls over this new information, the good doctor begins his end game.','[{"kind":"intro","label":"Opening","start":107,"end":197},{"kind":"outro","label":"Ending","start":1355,"end":1440}]','2012-12-06','98621');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#11','btooom',11,'Revival','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98622/original.jpg','With Ryouta out of the way, Himiko will be an easy target for Date, but Shiki has other plans for the doctor.','[{"kind":"outro","label":"Ending","start":1228,"end":1318}]','2012-12-13','98622');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('btooom#12','btooom',12,'Bonds','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/98623/original.jpg','Taira has lost it and is attacking his friends. Ryouta doesn''t want to fight but this time he truly might not have a choice.','[]','2012-12-20','98623');
