INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('sentenced-to-be-a-hero#11','sentenced-to-be-a-hero',11,'Sentence: Aid in Evacuation of Ioff Cheg Port 2','24:00',1440,'https://media.kitsu.app/episode/354318/thumbnail/medium-d95e492530e8edfaa351247a134083f1.jpeg','Xylo and Teoritta make a charge for Tua Jia tower while Kivia pursues a mystery of her own. (Source: Crunchyroll)','[]','2026-03-19','354318');
