INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#1','land-of-the-lustrous',1,'Phosphophyllite','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229824/original.jpg','Master Kongo finally decides to give the young Phos an assignment. Much to Phos dismay the assignment is to write an encyclopedia about the world. (Source: Amazon)','[]','2017-10-07','229824');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#2','land-of-the-lustrous',2,'Diamond','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229825/original.jpg','Phos is looking for ideas for the encyclopedia but is struggling to come up with anything. They go to Diamond for help as they have been working on a new technique. (Source: Amazon)','[]','2017-10-14','229825');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#3','land-of-the-lustrous',3,'Metamorphose','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229826/original.jpg','Unable to find Phos the group is concerned of what happened to them. However, Diamond is determined to bring Phos back. (Source: Amazon)','[]','2017-10-21','229826');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#4','land-of-the-lustrous',4,'Soul - Flesh - Bone','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229827/original.jpg','Phos is attacked, but manages to make a new friend out of the attacker. Together, both travel to the ocean where Phos learns more about the past. (Source: Amazon)','[]','2017-10-28','229827');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#5','land-of-the-lustrous',5,'Return','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229828/original.jpg','Phos is captured by the Lunarians. King reveals the truth behind the deception but is interrupted by their slumbering brother. (Source: Amazon)','[]','2017-11-04','229828');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#6','land-of-the-lustrous',6,'First Battle','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229829/original.jpg','Phos has recovered from the disaster at sea and has gained a new ability! What will happen to Phos as they put their skill to use as a lookout? (Source: Amazon)','[]','2017-11-11','229829');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#7','land-of-the-lustrous',7,'Hibernation','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229830/original.jpg','It''s winter time and everyone is discussing the best way to make it through the cold. Meanwhile, Phos gets roped into Antarcticite''s yearly duties. (Source: Amazon)','[]','2017-11-18','229830');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#8','land-of-the-lustrous',8,'Antarcticite','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229831/original.jpg','Pho has lost their arms, but Master Kongo believes them to be at the Chord Shore. Antarcticite makes it their mission to piece Phos back together. (Source: Amazon(','[]','2017-11-25','229831');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('land-of-the-lustrous#9','land-of-the-lustrous',9,'Spring','24:00',1440,'https://media.kitsu.app/episodes/thumbnails/229832/original.jpg','Spring comes with a bitter taste for Phos as they try to cope with the kidnapping of Antarcticite. In the meantime, the gems are trying to come to terms with the new Phos. (Source: Amazon)','[]','2017-12-02','229832');
