INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#1','yu-yu-hakusho-ghostfiles',1,'Surprised to be Dead','24:00',1440,'https://media.kitsu.app/episode/9397/thumbnail/medium-343c469248bf6f2e64a480907e2ff44b.jpeg','Yusuke Urameshi is hit by a car after saving a child who was playing with a ball in the street. He soon learns that the child would have lived anyway, and that the Spirit World was not expecting him to die. For this reason, he is then offered the chance to be revived by the mysterious Botan, Guardian of the river Styx. He initially refuses but accepts after seeing the people he thought did not care for him, including his childhood friend Keiko Yukimura, his mother Atsuko Urameshi, and his rival Kazuma Kuwabara grieving for him at his wake.','[{"kind":"intro","label":"Opening","start":165,"end":255},{"kind":"outro","label":"Ending","start":5,"end":95}]','1993-07-10','9397');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#2','yu-yu-hakusho-ghostfiles',2,'Koenma of the Spirit Realm! A trial Towards Resurrection.','24:00',1440,'https://media.kitsu.app/episode/9398/thumbnail/medium-02cdd8e5f9d9d1d5fbabef8b6595effa.jpeg','Yusuke meets Koenma, son of the ruler of the Spirit World, and is given the task of raising a spirit egg that, when hatched, may return him to his body. Yusuke possesses Kuwabara''s body to inform Keiko about his attempting to come back to life so that his body will not be cremated.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1305,"end":1421}]','1994-04-09','9398');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#3','yu-yu-hakusho-ghostfiles',3,'Kuwabara in a Corner! A Man''s Oath.','24:00',1440,'https://media.kitsu.app/episode/9399/thumbnail/medium-9c0b5c4e47cb64a706106b166b598705.jpeg','Yusuke discovers that Kuwabara has been forced by a teacher into a policy of strict nonviolence for a week — otherwise his best friend risks losing his job and being unable to support his family. Kuwabara bears the attacks, and when the teacher puts an additional stipulation that he and his friends must get more than 50 points on the next test, Yusuke helps him study by talking to him in his dreams. The teacher attempts to cheat his way out of the promise by altering Kuwabara''s paper, and Kuwabara almost punches him, but Yusuke calls out for him to stop. The teacher is forced to change the paper back, and Kuwabara''s friend keeps his job, with Kuwabara thanking Yusuke.','[{"kind":"outro","label":"Ending","start":1305,"end":1421}]','1994-04-09','9399');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#4','yu-yu-hakusho-ghostfiles',4,'Requirements for Lovers','24:00',1440,'https://media.kitsu.app/episode/9400/thumbnail/medium-c1276f50080c26e2a1a13d694422354a.jpeg','Yusuke''s house was set on fire while his mother was gone and Yusuke has to decide between saving Keiko or having any chance of returning to life. Yusuke chooses to throw his spirit egg into the fire to save Keiko, and by doing so, earns the right to return to life.','[{"kind":"intro","label":"Opening","start":0,"end":85},{"kind":"outro","label":"Ending","start":1300,"end":1421}]','1994-10-05','9400');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#5','yu-yu-hakusho-ghostfiles',5,'Yuusuke''s Back','24:00',1440,'https://media.kitsu.app/episode/9401/thumbnail/medium-69c31e947428aa3fbebee3acb4506e2d.jpeg','Yusuke is told by Koenma that he has one final chance to come back to life, but only if someone close to him kisses him within twenty-four hours. Trying to solicit Keiko''s aid, Yusuke manages to have Keiko kiss him just before the deadline.','[{"kind":"intro","label":"Opening","start":1,"end":115},{"kind":"outro","label":"Ending","start":1317,"end":1421}]','1994-10-05','9401');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#6','yu-yu-hakusho-ghostfiles',6,'The Three Youkai! Hiei, Kurama, Gouki','24:00',1440,'https://media.kitsu.app/episode/168547/thumbnail/medium-ef0f5d201b1098f2b4deb81e7d961a72.jpeg','Koenma reveals that Yusuke is a Spirit Detective, and must use his unique abilities to battle demons and other threats to the Living World. Koenma additionally gives Yusuke a mission: he must recover three artifacts stolen by master thieves of the Spirit World.','[{"kind":"outro","label":"Ending","start":1321,"end":1421}]','1992-10-10','168547');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#7','yu-yu-hakusho-ghostfiles',7,'Gouki and Kurama','24:00',1440,'https://media.kitsu.app/episode/168548/thumbnail/medium-a53c9bad745e5d155442822515fc02fa.jpeg','Yusuke discovers the first and second thieves, and the artifacts. Gouki, the first thief, possesses the Orb of Baast, and Kurama, the second thief, has the Forlorn Hope. Yusuke defeats Gouki, recovering his artifact. He meets with Kurama and learns that he plans to use the Forlorn Hope to sacrifice himself to save his human "mother." Yusuke, believing that Kurama''s sacrifice would cause his mother pain, gives some of his life force so that Kurama will not have to die, and claims the mirror.','[{"kind":"intro","label":"Opening","start":0,"end":85},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1992-10-17','168548');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#8','yu-yu-hakusho-ghostfiles',8,'The Three Eyes of Hiei','24:00',1440,'https://media.kitsu.app/episode/168549/thumbnail/medium-9dcfdf13263c67d7cf3f7c5e2473bb2d.jpeg','Yusuke battles the last thief, Hiei, who has taken Keiko hostage to get the last three treasures. With Hiei''s Jagan eye affording him additional perception, Yusuke finds his fight difficult, but he manages to trick Hiei by firing his Spirit Gun off a mirror in order to hit Hiei in his blind spot, defeating him.','[{"kind":"intro","label":"Opening","start":0,"end":114},{"kind":"outro","label":"Ending","start":1317,"end":1421}]','1992-10-24','168549');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#9','yu-yu-hakusho-ghostfiles',9,'The Search Begins','24:00',1440,'https://media.kitsu.app/episode/168550/thumbnail/medium-d42e6baae07a465acfcd1f72bf5808f0.jpeg','Yusuke enters a fighting tournament at Koenma''s behest. The winner of the tournament gets to learn the secret techniques of Genkai, a master psychic, and Koenma knows that there is a demon named Rando who will be after Genkai''s techniques. To his surprise, Yusuke finds his old rival Kuwabara at the tournament, seeking to learn more about his powers. Yusuke and Kuwabara inadvertently qualify for Genkai''s tournament due to their high amount of spirit energy.','[{"kind":"intro","label":"Opening","start":0,"end":108},{"kind":"outro","label":"Ending","start":1401,"end":1421}]','1992-10-31','168550');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#10','yu-yu-hakusho-ghostfiles',10,'Kuwabara''s Spirit Sword','24:00',1440,'https://media.kitsu.app/episode/168551/thumbnail/medium-067f45705e3e2173ffd99ef9d27eb377.jpeg','Eight finalists are entered into a tournament, and the first round takes place in complete darkness. Kuwabara discovers that he has his own special technique — a sword formed of energy. Using this technique, he defeats his first opponent, moving onto the next round of the tournament.','[]','1992-11-07','168551');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#11','yu-yu-hakusho-ghostfiles',11,'Hard Fights for Yusuke','24:00',1440,'https://media.kitsu.app/episode/168552/thumbnail/medium-aaa62919b3e3c79271f5efa6fccf221f.jpeg','Yusuke defeats his first opponent by placing a lit cigarette on him, allowing him to see him and shoot him in the darkness. The finals then take place on a hill, and Yusuke has to face an opponent whose preferred weapon, shuriken, have the ability to home in on their targets. Yusuke ultimately manages to overcome him, proceeding onto the final round of the tournament.','[]','1992-11-14','168552');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#12','yu-yu-hakusho-ghostfiles',12,'Rando Rises, Kuwabara Falls','24:00',1440,'https://media.kitsu.app/episode/9403/thumbnail/medium-4ace79f75573ad8434983170e2f8a3a9.jpeg','Kuwabara faces Shorin, who reveals more than his initial demeanor entails. Using techniques of spirit mediums and masters of centuries past, Shorin is identified to be Rando by Genkai. Rando proves too powerful for Kuwabara, and he shrinks and defeats him.','[{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1992-11-21','9403');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#13','yu-yu-hakusho-ghostfiles',13,'Yusuke VS. Rando: 99 Attacks','24:00',1440,'https://media.kitsu.app/episode/9404/thumbnail/medium-b0a3f61bdfc9ffe3d6e4ea9cbc3fce70.jpeg','Rando reveals himself to Yusuke, using a barrage of stolen techniques against him. Yusuke manages to overcome Rando by tricking him, turning his technique against him, and he becomes Genkai''s student.','[]','1992-11-28','9404');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#14','yu-yu-hakusho-ghostfiles',14,'The Beasts of Maze Castle','24:00',1440,'https://media.kitsu.app/episode/9405/thumbnail/medium-bdf20957dc95f1eba0234f9e9ed634d4.jpeg','Yusuke returns from training with Genkai to discover that his home city has been invaded by Makai Insects controlled by the four Saint Beasts. Kurama and Hiei, with the offer of pardons from their past crimes, have been sent to help Yusuke and Kuwabara with this new mission.','[{"kind":"outro","label":"Ending","start":1334,"end":1417}]','1992-12-05','9405');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#15','yu-yu-hakusho-ghostfiles',15,'Beautiful Dance of the Rose! The Elegant Kurama','24:00',1440,'https://media.kitsu.app/episode/9406/thumbnail/medium-f9c96ceaed2a8a6c6a23f7db4503eb36.jpeg','Kurama faces off against Genbu, the first of the four Saint Beasts and a master of stone-based abilities. Using his plant abilities and intuition, Kurama identifies Genbu''s weakness and defeats him.','[{"kind":"intro","label":"Opening","start":25,"end":115}]','1992-12-12','9406');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#16','yu-yu-hakusho-ghostfiles',16,'Byakko, the White Tiger','24:00',1440,'https://media.kitsu.app/episode/9407/thumbnail/medium-a1e1ce4f905c848d408763dfddadb308.jpeg','Kuwabara demands to fight the next opponent himself, and encounters Byakko, the second Saint Beast. With Byakko''s ability to absorb energy, Kuwabara''s attacks prove fruitless. Determined to win, Kuwabara overwhelms Byakko''s absorption ability, defeating him.','[{"kind":"intro","label":"Opening","start":107,"end":197}]','1992-12-19','9407');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#17','yu-yu-hakusho-ghostfiles',17,'Byakko''s Lair','24:00',1440,'https://media.kitsu.app/episode/9408/thumbnail/medium-4e1b7507420fb7b1e5fa2d29103e2bef.jpeg','Byakko is seemingly defeated, but appears once more to fight Kuwabara in a room full of molten lava. Using a new technique, Byakko turns the tables on Kuwabara, who desperately claims victory by sending Byakko into the lava.','[{"kind":"outro","label":"Ending","start":1334,"end":1421}]','1992-12-26','9408');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#18','yu-yu-hakusho-ghostfiles',18,'Seiryu, the Blue Dragon','24:00',1440,'https://media.kitsu.app/episode/9409/thumbnail/medium-ff7eea3ff196cdd266b9613591e475b6.jpeg','The third Saint Beast, Seiryu, appears, and battles Hiei. Although Seiryu seems to have the advantage, Hiei reveals that he has been merely toying with him, and easily reverses all of his ice attacks. As Seriyu attempts to respond, Hiei cuts him down with his sword.','[]','1993-01-09','9409');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#19','yu-yu-hakusho-ghostfiles',19,'Suzaku, Leader of the Beasts','24:00',1440,'https://media.kitsu.app/episode/9410/thumbnail/medium-8b5e2333d8c395ef4d72534e91649cba.jpeg','Yusuke fights with the last of the Saint Beasts, Suzaku, who controls the Makai Insects. Despite his determination to win, Yusuke has difficulty in dealing with Suzaku''s lightning abilities. Elsewhere, the Makai Insect-infected humans begin closing in on Keiko.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-01-16','9410');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#20','yu-yu-hakusho-ghostfiles',20,'Seven Ways to Die','24:00',1440,'https://media.kitsu.app/episode/9411/thumbnail/medium-5d3bc1a2888a18979ba71149b19644c3.jpeg','Suzaku reveals his secret technique — the ability to split himself into seven entities, overwhelming Yusuke. In the human world, Keiko and Botan try to remain safe from attack from the insect-infested humans.','[{"kind":"outro","label":"Ending","start":1342,"end":1421}]','1993-01-23','9411');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#21','yu-yu-hakusho-ghostfiles',21,'Yusuke''s Sacrifice','24:00',1440,'https://media.kitsu.app/episode/9412/thumbnail/medium-efaa8d0b53cbe1c7bf5e35b092224dd7.jpeg','Yusuke, confronted with an image of Keiko with her life threatened, finally defeats Suzaku by using the last of his life energy to destroy all of his clones, and barely survives with Kuwabara transferring some of his own energy to Yusuke.','[{"kind":"outro","label":"Ending","start":1334,"end":1421}]','1993-01-30','9412');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#22','yu-yu-hakusho-ghostfiles',22,'Lamenting Beauty','24:00',1440,'https://media.kitsu.app/episode/9413/thumbnail/medium-101236dce0eba610cfdee400a13d9648.jpeg','Yukina, an ice apparition, who also happens to be Hiei''s twin sister, was being held captive by the Black Black Club founder, Gonzo Tarukane.','[{"kind":"outro","label":"Ending","start":1329,"end":1421}]','1993-02-06','9413');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#23','yu-yu-hakusho-ghostfiles',23,'The Toguro Brothers Gang','24:00',1440,'https://media.kitsu.app/episode/9414/thumbnail/medium-ca60ff2a10d1ffd94e911de421b2a786.jpeg','Yusuke and his friends fight their way through the human and demon guards surrounding Tarukane''s stronghold. Meanwhile, Tarukane bets on his demon guards killing Yusuke''s group with the Black Black Club, losing money every round to Sakyo, who bets on Yusuke''s side.','[{"kind":"intro","label":"Opening","start":1,"end":91}]','1993-02-13','9414');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#24','yu-yu-hakusho-ghostfiles',24,'The Deadly Triad','24:00',1440,'https://media.kitsu.app/episode/9415/thumbnail/medium-c4f68d1fcb1ea51e764629c482dae548.jpeg','Yusuke, Kuwabara, and Botan must face three demons known throughout the Spirit World as The Triad. All three are overwhelmed by Yusuke''s group. At the same time, Sakyo''s successful bets on Yusuke''s group have earned him an enormous amount of money.','[]','1993-02-20','9415');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#25','yu-yu-hakusho-ghostfiles',25,'Kuwabara''s Fight of Love','24:00',1440,'https://media.kitsu.app/episode/9416/thumbnail/medium-ff8b746f65d1ecedcad7125251d5a9b3.jpeg','Yusuke and Kuwabara encounter the powerful Toguro Brothers while Kurama tries to keep Hiei from carrying out his own plans. At the same time, Sakyo has bet an enormous fortune on Yusuke and Kuwabara''s victory, constituting all of his assets. Kuwabara''s determination enables them to defeat the Toguro Brothers, and Yukina prevents Hiei from killing Tarukane.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-02-27','9416');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#26','yu-yu-hakusho-ghostfiles',26,'Toguro Returns','24:00',1440,'https://media.kitsu.app/episode/9417/thumbnail/medium-228c75271ebbe41fac779b67f86c6919.jpeg','Yusuke Urameshi once again meets Toguro, who forces Yusuke to enter the "Dark Tournament," or he will kill all of Yusuke''s friends. Yusuke and his allies begin a two-month training period. After this period, they join together, alongside a disguised fifth fighter that Yusuke brings, as Team Urameshi.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-03-06','9417');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#27','yu-yu-hakusho-ghostfiles',27,'The Dark Tournament Begins','24:00',1440,'https://media.kitsu.app/episode/9418/thumbnail/medium-c7df3d8be8e816cad578c1868c4be6a5.jpeg','Team Urameshi finds out that the preliminary competition is on the ship itself, on the way to Hanging Neck Island. Yusuke and his friends, displaying their enhanced abilities, easily dispose of the demons aboard the ship to pass the preliminaries.','[{"kind":"outro","label":"Ending","start":1325,"end":1421}]','1993-03-13','9418');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#28','yu-yu-hakusho-ghostfiles',28,'First Fight','24:00',1440,'https://media.kitsu.app/episode/9419/thumbnail/medium-9efbc0add57665b0ea7fb5a70e1d629d.jpeg','Kazuma Kuwabara faces off against Rinku, the first member of Team Rokuyukai. Although Kuwabara displays his newfound ability to wield two swords at once, he is unable to overcome Rinku''s assault.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-03-20','9419');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#29','yu-yu-hakusho-ghostfiles',29,'Flowers of Blood','24:00',1440,'https://media.kitsu.app/episode/9420/thumbnail/medium-681442af9d167de5b6f30df3853ff825.jpeg','Kurama battles Roto, who threatens to have his brother kill Kurama''s human mother. However, Kurama deceives Roto by conversing with him until a seed Kurama planted in Roto at the start of the round blooms, killing Roto from the inside.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-03-27','9420');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#30','yu-yu-hakusho-ghostfiles',30,'Dragon of the Darkness Flame','24:00',1440,'https://media.kitsu.app/episode/9421/thumbnail/medium-18ca4b0dedd330519818158b892be370.jpeg','The leader of Team Rokuyukai, Zeru, challenges Hiei, who is seemingly overwhelmed by the initial fire assault. However, Hiei''s Jagan enables him to shrug off the assault without incident, and he uses his new technique, the Dragon of the Darkness Flame, to obliterate Zeru.','[{"kind":"outro","label":"Ending","start":1320,"end":1421}]','1993-04-10','9421');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#31','yu-yu-hakusho-ghostfiles',31,'Stumbling Warrior','24:00',1440,'https://media.kitsu.app/episode/168576/thumbnail/medium-db8acbfd04d3b3136f489b3fe0d9ff17.jpeg','The final member of Team Rokuyukai, Chu, battles Yusuke. Even with his new abilities, Yusuke is evenly matched against Chu.','[{"kind":"intro","label":"Opening","start":606,"end":696},{"kind":"outro","label":"Ending","start":620,"end":710}]','1993-04-17','168576');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#32','yu-yu-hakusho-ghostfiles',32,'Knife-Edge Death Match','24:00',1440,'https://media.kitsu.app/episode/168583/thumbnail/medium-a7a613722eecf64d87f4dcf70cf1742a.jpeg','Yusuke and Chu battle between two knives, with the loser receiving death at the hands of the victor. After a brutal fight, Yusuke overcomes Chu, but spares his life.','[]','1993-04-24','168583');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#33','yu-yu-hakusho-ghostfiles',33,'A Day in Waiting','24:00',1440,'https://media.kitsu.app/episode/168586/thumbnail/medium-f9b8e25064007102446f961231f40370.jpeg','Team Urameshi rests a day before their next match, only to watch Toguro effortlessly defeat an entire team by himself.','[{"kind":"outro","label":"Ending","start":1334,"end":1421}]','1993-05-01','168586');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#34','yu-yu-hakusho-ghostfiles',34,'Percentage of Victory','24:00',1440,'https://media.kitsu.app/episode/168589/thumbnail/medium-0bbec547bbf142f4f43020f272794d5e.jpeg','Team Urameshi participates in a 3-on-3 battle with the Dr. Ichigaki Team, but the members of the other team are revealed to be humans. Due to Ichigaki''s experiments and their powerful spirit powers, they prove to be a match for Team Urameshi.','[{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1993-05-08','168589');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#35','yu-yu-hakusho-ghostfiles',35,'Glimpse Beneath the Mask','24:00',1440,'https://media.kitsu.app/episode/168594/thumbnail/medium-6e537b1cd2bda7db1a7d258cfe573d69.jpeg','The Masked Fighter of Team Urameshi is revealed to be a young woman with pink hair, while the battle with the Dr. Ichigaki Team continues.','[{"kind":"intro","label":"Opening","start":0,"end":101},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-05-15','168594');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#36','yu-yu-hakusho-ghostfiles',36,'Ambition Destroyed: A Trial of Light','24:00',1440,'https://media.kitsu.app/episode/168598/thumbnail/medium-d3e9470c2f069983c043e184e7e6a6a6.jpeg','After Dr. Ichigaki''s fighters are defeated by the Masked Fighter''s Spirit Wave technique, Dr. Ichigaki battles Team Urameshi by transforming into a monstrous creature, but is quickly bested by an enraged Yusuke.','[{"kind":"intro","label":"Opening","start":0,"end":105},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-05-22','168598');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#37','yu-yu-hakusho-ghostfiles',37,'Master of Disguise','24:00',1440,'https://media.kitsu.app/episode/168603/thumbnail/medium-fe074aa014c61069f9442207406e1ecd.jpeg','With Hiei and the Masked Fighter trapped by a disguised medical attendant, and Kuwabara badly injured, only Yusuke and Kurama are left to battle Team Mashoutsukai.','[{"kind":"outro","label":"Ending","start":1319,"end":1420}]','1993-05-29','168603');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#38','yu-yu-hakusho-ghostfiles',38,'Kurama''s Stand','24:00',1440,'https://media.kitsu.app/episode/168612/thumbnail/medium-50fa2f647cba959f918890839fb0aec6.jpeg','Kurama''s arms and legs still tethered down by Gama''s first curse, and his energy sealed inside him by the dying efforts of Gama. He barely defeats the ice master Touya by implanting his plants into his own body to use as a weapon, but then the brutish Bakken steps into the ring.','[{"kind":"intro","label":"Opening","start":0,"end":101},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-06-05','168612');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#39','yu-yu-hakusho-ghostfiles',39,'Crushing Revenge','24:00',1440,'https://media.kitsu.app/episode/168621/thumbnail/medium-a9e316ead853bf4437afa7c226dc0170.jpeg','Bakken brutally assaults the comatose Kurama, but spares his life after seeing that Yusuke would have killed Bakken if he had continued. In retribution for Bakken''s cruelty against Kurama, Yusuke utterly defeats him.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-06-12','168621');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#40','yu-yu-hakusho-ghostfiles',40,'Jin, the Wind Master','24:00',1440,'https://media.kitsu.app/episode/168628/thumbnail/medium-c5769906f55f600a1053fd00253001f0.jpeg','The fight starts with Jin in the air, using his wind to fly. Jin goes on the offensive, and Yusuke is unable to defend himself from these aerial assaults. Yusuke tries a couple of strategies to counter Jin''s attacks, especially the wind master''s Tornado Fists, but he is unsuccessful. Finally, both fighters decided to go all out and really start trying. Jin creates a Tornado Fist on both hands, and Yusuke adopts a new fighting stance.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-06-19','168628');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#41','yu-yu-hakusho-ghostfiles',41,'Reverse Decisions','24:00',1440,'https://media.kitsu.app/episode/168631/thumbnail/medium-8adb6d434bf775955b82cca2a7af2da8.jpeg','The epic climax to the fight between Yusuke and Jin is about to happen. Jin is poised to attack with his Double Tornado Fists, and Yusuke is ready to counter using his new attack, the Spirit Wave. As the fight ends, Team Mashoutsukai''s owner thinks of another way to complicate things. How will his cheating change matters? And what does this mean for Team Urameshi?','[{"kind":"outro","label":"Ending","start":1327,"end":1421}]','1993-06-26','168631');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#42','yu-yu-hakusho-ghostfiles',42,'A Matter of Love and Death','24:00',1440,'https://media.kitsu.app/episode/168635/thumbnail/medium-99fe0760b89e2cb2743c5a3701bb6707.jpeg','The fight between Team Urameshi and Team Masho is almost over. Only one fight remains, Risho versus Kuwabara. The fight has already started, and Kuwabara is being beat up pretty bad. Risho continues to hammer Kuwabara, and then starts to use his Shinobi mastery of earth. He creates advanced armor, and reigns more furious meteor attacks on the weakened Kuwabara. With all his spirit energy exhausted, Kuwabara decides to use a desperate measure, but someone is in the audience calling to him. Who is it? Will they give Kuwabara the strength to continue?','[{"kind":"outro","label":"Ending","start":1334,"end":1421}]','1993-07-03','168635');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#43','yu-yu-hakusho-ghostfiles',43,'The Masked Fighter Revealed','24:00',1440,'https://media.kitsu.app/episode/168639/thumbnail/medium-49a7750a377a621b08e9280a38165028.jpeg','After talking to Keiko, Yusuke is confronted by Botan. She tells him his Spirit Beast will hatch soon. Koenma startles the two and show Yusuke his big egg. Koenma reminds him that the egg will consume every part of him if he was evil. The egg hatches and no one sees where the beast is. They look at Yusuke and they see the beast. It is a small blue bird with big floppy ears. Everyone mocks him. The next day, the team tries to scope out the competition. Team Uraotogi takes care of Team Gokai Six in two minutes. Only the badly injured Hiei and Kurama watch the fight. Kuwabara tells them to go to Yukina for healing, not knowing she is Hiei''s sister. He mentions her quest and Yusuke and Kurama start mocking Hiei. Then, Team Toguro shows up. Younger Toguro and his older brother are there, as well as two other men, one in black with a mask and the other clad in armor. The crowd gives them praise. Then Yusuke and the Masked Fighter get into a fight. She says she would be a better leader than Yusuke. She leads him to a secluded place and reveals herself to be Genkai. She asks him to shoot a rock. He does. Then she shoots a mountain. As she does, she turns into her younger self. She says this is the effect of the Spirit Wave. She tells Yusuke he has one last test.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-07-10','168639');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#44','yu-yu-hakusho-ghostfiles',44,'Yusuke''s Final Test','24:00',1440,'https://media.kitsu.app/episode/168643/thumbnail/medium-97fb9648c74a40d94b8a155059fe5ebc.jpeg','As the semi-finals begin and Team Urameshi prepares to face off against Team Uraotogi, Yusuke is being administered his final test elsewhere by Genkai. In the first match, Hiei effortlessly dispatches the first fighter, leading Kuro Momotaro to enter the ring.','[{"kind":"intro","label":"Opening","start":0,"end":101},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-07-17','168643');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#45','yu-yu-hakusho-ghostfiles',45,'Hiei Battles On','24:00',1440,'https://media.kitsu.app/episode/168648/thumbnail/medium-e7dc0fb6bf6eb03a61bff521ac217be5.jpeg','Hiei battles Kuromomotaro, whose transformations make Hiei''s techniques useless. Unable to use the Dragon of the Darkness Flame, lest it consume him in the process, Hiei is left with dwindling options.','[{"kind":"outro","label":"Ending","start":1320,"end":1421}]','1993-07-24','168648');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#46','yu-yu-hakusho-ghostfiles',46,'Many Faces, Many Forms','24:00',1440,'https://media.kitsu.app/episode/168651/thumbnail/medium-625335aa8821f492501907cd0d9d8c02.jpeg','Hiei''s attacks are ineffective against Kuro Momotaro, and he is forced to use his powers in an unorthodox fashion - channeling the Dragon of the Darkness Flame through his sword to dispatch Kuro Momotaro.','[{"kind":"intro","label":"Opening","start":2,"end":92}]','1993-07-31','168651');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#47','yu-yu-hakusho-ghostfiles',47,'Legendary Bandit: Yoko Returns','24:00',1440,'https://media.kitsu.app/episode/168657/thumbnail/medium-5ce6fe75595998e3c2c4129918ab4877.jpeg','Ura Urashima has confined the ring with a peripheral space made of his fishing line; he unleashes smoke that makes everyone''s age reverse, thereby making them grow younger. However, this only transforms Kurama into his original and far stronger form, which is the fox demon, Yoko Kurama. Ura Urashima finds himself in big trouble as Kurama calls forth a Death Tree and tries to find the real motivations for Team Uraotogi''s participation in the tournament. Meanwhile, Yusuke continues to struggle with the absorption of the Spirit Wave Orb. Will he survive?','[{"kind":"intro","label":"Opening","start":1,"end":87},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-08-07','168657');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#48','yu-yu-hakusho-ghostfiles',48,'The Cape of No Return','24:00',1440,'https://media.kitsu.app/episode/168663/thumbnail/medium-46c0fb91a2c4bb2d2b25b0dc10a13044.jpeg','Kuwabara fights against the team leader, Shishiwakamaru. However, he is quickly sent through the Cape of No Return, and transported out of the ring.','[{"kind":"outro","label":"Ending","start":1335,"end":1414}]','1993-08-14','168663');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#49','yu-yu-hakusho-ghostfiles',49,'Genkai''s Strength','24:00',1440,'https://media.kitsu.app/episode/168672/thumbnail/medium-7afcf552c9627de8d878d054a94b773d.jpeg','With most of her power taken by Yusuke, Genkai struggles against Shishiwakamaru, but Genkai manages to turn the tables by using Shishiwakamaru''s energy against him.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1993-08-21','168672');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#50','yu-yu-hakusho-ghostfiles',50,'Suzuka''s Challenge','24:00',1440,'https://media.kitsu.app/episode/168675/thumbnail/medium-c8f1855017d828d0a4f88e096763672b.jpeg','Kuwabara steps into the ring again to fight against Suzuki, but runs straight into his trap, transporting him again into the old stadium. Genkai steps in next, and defeats Suzuki without wasting any spirit energy.','[{"kind":"intro","label":"Opening","start":1,"end":91},{"kind":"outro","label":"Ending","start":1335,"end":1412}]','1993-08-28','168675');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#51','yu-yu-hakusho-ghostfiles',51,'Arch-Rivals','24:00',1440,'https://media.kitsu.app/episode/168678/thumbnail/medium-93338355109b9e9b80c7e5a663ed14c8.jpeg','Team Toguro easily wins their semi-final match against Team Gorenja. Meanwhile, Genkai goes to confront Younger Toguro, who is absent from the semi-finals. The link between Genkai and Toguro is explored, and a fight is upcoming.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-09-04','168678');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#52','yu-yu-hakusho-ghostfiles',52,'The Death of Genkai','24:00',1440,'https://media.kitsu.app/episode/168680/thumbnail/medium-86fc332226abc8d16f11d64be3b0dc6b.jpeg','With both Ura Urashima and the newly transformed Yoko Kurama trapped in the ring, the true battle begins','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-09-11','168680');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#53','yu-yu-hakusho-ghostfiles',53,'Overcoming Grief','24:00',1440,'https://media.kitsu.app/episode/168682/thumbnail/medium-d7a4205b866c7ea31ba3e808a54e0045.jpeg','As Team Urameshi mourns Genkai''s passing, they prepare for the final match against Team Toguro.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1993-09-18','168682');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#54','yu-yu-hakusho-ghostfiles',54,'The Beginning of the End','24:00',1440,'https://media.kitsu.app/episode/168684/thumbnail/medium-a82b4af2bbb055f94b530d605ba1b3af.jpeg','The tournament finals are set to begin. But the rules state that each team must have five members to compete. With each team having only four fighters, two competitors step up to join with each team no matter what the consequences. Who are the two new fighters and what could they possibly bring to the team?','[{"kind":"intro","label":"Opening","start":1,"end":114},{"kind":"outro","label":"Ending","start":1334,"end":1417}]','1993-09-25','168684');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#55','yu-yu-hakusho-ghostfiles',55,'The Beast Within','24:00',1440,'https://media.kitsu.app/episode/168686/thumbnail/medium-afd86b84b69787071deae912cf4c2629.jpeg','The Dark Tournament finals have finally started, the first fight places Kurama against Karasu. Kurama, believing that the only chance for him to win is to transform into Yoko Kurama, starts trying to stall for time. Meanwhile, Karasu has every intention to mercilessly enjoy this fight, leaving Kurama to try to think of a way to stay alive long enough to transform.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1333,"end":1421}]','1993-10-02','168686');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#56','yu-yu-hakusho-ghostfiles',56,'Yoko''s Magic','24:00',1440,'https://media.kitsu.app/episode/9422/thumbnail/medium-6a33dd5d2739669c23b59da213b91938.jpeg','Yoko Kurama reverts into his human form, giving Karasu the advantage. In response, Kurama plays on Karasu''s overconfidence, and uses a desperate final attack to secure victory.','[{"kind":"intro","label":"Opening","start":0,"end":100},{"kind":"outro","label":"Ending","start":1312,"end":1421}]','1993-10-09','9422');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#57','yu-yu-hakusho-ghostfiles',57,'Beneath Bui''s Armor','24:00',1440,'https://media.kitsu.app/episode/9423/thumbnail/medium-72555ce1398a6007253a214105923a40.jpeg','The battle between Kurama and Karasu has come to an end, and an unexpected verdict is made. Soon, Hiei gets in the ring, eager to take on his opponent. Bui, a mysterious fighter, with an immense power hidden beneath his armor...','[{"kind":"intro","label":"Opening","start":2,"end":92},{"kind":"outro","label":"Ending","start":1336,"end":1418}]','1993-10-16','9423');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#58','yu-yu-hakusho-ghostfiles',58,'Wielder of the Dragon','24:00',1440,'https://media.kitsu.app/episode/9424/thumbnail/medium-eb6e0f7e267ce1e88059da1f72ab7437.jpeg','Hiei unleashes his most powerful attack, the Dragon of the Darkness Flame. But Bui is able to turn the Dragon against it''s master and it seemed as if the attack destroyed him completely. Juri was just lying on the floor while they were fighting. Then when the crowd saw it, Juri got her legs to stand up. She was just about to announce that Bui is the winner, when Hiei appeared and was undamaged. Hiei later said that he was the only one that could completely control the "Power of the Dragon" because he was the dragon.','[{"kind":"intro","label":"Opening","start":1,"end":91},{"kind":"outro","label":"Ending","start":1335,"end":1420}]','1993-10-23','9424');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#59','yu-yu-hakusho-ghostfiles',59,'The Shadow of Elder Toguro','24:00',1440,'https://media.kitsu.app/episode/9425/thumbnail/medium-e87223db5be1244e163eda513657d7d8.jpeg','During his match with Toguro, Kuwabara is told of Genkai''s death. With extreme rage, Kuwabara strikes Toguro with the Trial Sword, splitting the demon in half. The arena watches in horror as the evil Toguro rises from the arena floor unharmed.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1420}]','1993-10-30','9425');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#60','yu-yu-hakusho-ghostfiles',60,'Sakyo''s Proposal','24:00',1440,'https://media.kitsu.app/episode/9426/thumbnail/medium-87d91e1ce5166dfd617fbb2ea6edcc4d.jpeg','Kuwabara''s fight with the Elder Toguro brother comes to a smashing conclusion, leading into Yusuke''s grudge match with younger Toguro. But before that bout can begin, intrigue at Team Toguro culminates in a shocking proposal from Sakyo and an even more shocking response from Koenma.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1993-11-06','9426');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#61','yu-yu-hakusho-ghostfiles',61,'Two Great Rivals','24:00',1440,'https://media.kitsu.app/episode/9427/thumbnail/medium-13ea3cfa17a9399520d3268f0e1e20d8.jpeg','Rinku, Chu, Touya, and Jin are now allies of Yusuke joining his side. En, Ryo and Kai are part of the audience and Suzuki is also supporting Yusuke, as they come to watch the final match between Yusuke and the Younger Toguro brother. The fight comes to a standstill, as both contestants prepare to attack. Yusuke shoots a massive spirit gun blast that sends the Younger Toguro out of the stadium. However, the Younger Toguro returns, surprisingly uninjured by Yusuke''s attack.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1993-11-13','9427');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#62','yu-yu-hakusho-ghostfiles',62,'Toguro''s True Power','24:00',1440,'https://media.kitsu.app/episode/9428/thumbnail/medium-7130feaaea3a44e656da5bc0abc853d7.jpeg','Yusuke removes the spirit cuffs from the arms and legs, chained to him by his master Genkai, unlocking the full power of his spirit energy. Even after Yusuke inflicts a barrage of hits towards Toguro, the latter remains uninjured. Toguro presents one hundred percent of his total strength, overwhelming Yusuke.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1320,"end":1421}]','1993-11-20','9428');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#63','yu-yu-hakusho-ghostfiles',63,'Yusuke''s Despair','24:00',1440,'https://media.kitsu.app/episode/9429/thumbnail/medium-9001c1788205f107fcfb54718f8e3802.jpeg','Yusuke is reminded of his childhood life with Keiko when she cries out his name during the battle. Genkai possesses Pu and suggests that Younger Toguro should kill one of Yusuke''s friends in order to increase his power exponentially. The Younger Toguro chooses Kuwabara to die at his hands.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1993-11-27','9429');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#64','yu-yu-hakusho-ghostfiles',64,'Final Battle','24:00',1440,'https://media.kitsu.app/episode/9430/thumbnail/medium-79bac42afe9e2dadfb041679cad28319.jpeg','With Kuwabara dead, Yusuke''s power rises with his grief. In response, Toguro powers to one hundred and twenty percent of his total power. As the two clash, Toguro manages to block the final blast of Yusuke''s Spirit Gun Mega, but ends up crumbling down in defeat after its completion. Finally, Team Urameshi is then crowned the winners of the Dark Tournament.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1993-12-04','9430');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#65','yu-yu-hakusho-ghostfiles',65,'The Stadium Explodes','24:00',1440,'https://media.kitsu.app/episode/9431/thumbnail/medium-7ec76f46c073cc527301bb5cbb2d653d.jpeg','It is quite a shock that Kuwabara is actually alive, as his vital points were not damaged. To fulfill his promise of defeat, Sakyo commits suicide by detonating the stadium, with the participants and spectators barely able to escape, destroying all his progress in his proposal. Keiko, feeling catatonic, is unresponsive to Botan''s voice, and Yusuke later slaps her back to her senses, but Keiko angrily slaps Yusuke back in return. The protagonists make it out alive at the last minute.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1318,"end":1421}]','1993-12-11','9431');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#66','yu-yu-hakusho-ghostfiles',66,'Toguro''s Reward','24:00',1440,'https://media.kitsu.app/episode/9432/thumbnail/medium-7941bd004d3b6dad040f52225c646452.jpeg','The protagonists prepare to sail home since the tournament has ended. In the Spirit World, the Younger Toguro demands to go to the most brutal level of the underworld to repent for his deeds in life. It is explained by Ayame that the Younger Toguro had been psychologically scarred fifty years ago by a demon named Kairin, who killed all the students of his dojo. Genkai confronts the Younger Toguro for blaming himself for his wrongdoings. Genkai is resurrected in the Living World as the prize for winning the tournament.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1993-12-18','9432');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#67','yu-yu-hakusho-ghostfiles',67,'A New Beginning','24:00',1440,'https://media.kitsu.app/episode/9433/thumbnail/medium-ebca7573bc8bdab2d0c9e7d434615f42.jpeg','After he returns to his hometown from the Dark Tournament in Hanging Neck Island, Yusuke Urameshi runs afoul of three high school boys, Asato Kido, Mitsunari Yanagisawa and Yu Kaitou. Using his psychic abilities, Kito paralyzes Yusuke by stepping on his shadow, and they kidnap him in the process. Kido, Yanagisawa, and Kaito leave a message for Kazuma Kuwabara and Botan, who decide to rescue Yusuke.','[{"kind":"outro","label":"Ending","start":1304,"end":1421}]','1993-12-25','9433');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#68','yu-yu-hakusho-ghostfiles',68,'The Trap Set On Siciyu House','24:00',1440,'https://media.kitsu.app/episode/9434/thumbnail/medium-377319171df9caef970d5b64e709d999.jpeg','Kuwabara and Botan find gather Kurama and Hiei to aid them in rescuing Yusuke. Although Hiei is reluctant to do so, Botan convinces him to come with them. The four head to the mansion where Yusuke is held, and find Kaito in the first room. Kaito explains that they have entered a realm of four dimensions, in which fantasy can be altered into reality. Hiei has been turned to stone after falling prey by one of Kaito''s attacks, one that forbids from saying the word "hot". Kuwabara is unable to snatch from Yanagisawa the key to the room leading toward Yusuke. Kurama has agreed to a game of taboo against Kaito.','[{"kind":"intro","label":"Opening","start":0,"end":113},{"kind":"outro","label":"Ending","start":1303,"end":1421}]','1994-01-08','9434');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#69','yu-yu-hakusho-ghostfiles',69,'Taboo no Power! Zouba no Zunou','24:00',1440,'https://media.kitsu.app/episode/9435/thumbnail/medium-5b17e78050a14d7090190c7b60136ba4.jpeg','Kuwabara and Botan also turns into stone due to saying hot as well. Kurama discreetly takes the key from Yanagisawa. Kurama challenges Kaito to a game of taboo in which letters of the alphabet become taboo one by one over the course of the game, waging their souls as their bids. Kurama surrounds himself with his manifested plants while Kaito goes to the restroom, emerging when only the last two letters are left. Kurama yells to scare him, but he manages not to cry out. It is until Kurama makes silly faces at Kaito that cause the latter to laugh, thereby breaking the taboo. Kaito loses his own soul, thus freeing the others. Now it''s time to continue to the next opponent of the Mystery Trio.','[{"kind":"intro","label":"Opening","start":0,"end":100},{"kind":"outro","label":"Ending","start":1334,"end":1421}]','1994-01-15','9435');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#70','yu-yu-hakusho-ghostfiles',70,'Surprising Truth! The Mystery Newly Appeared!','24:00',1440,'https://media.kitsu.app/episode/9436/thumbnail/medium-841dcd17f43fd6d937161eb544d2938a.jpeg','One of the kidnappers, Mitsunari Yanagisawa, disguises himself as one of Yusuke''s friends, forcing Yusuke to determine who is the impostor. Unable to determine who actually is the imposter, Yusuke manages to use his intuition to successfully determine that "Kuwabara" is the imposter.','[]','1994-01-22','9436');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#71','yu-yu-hakusho-ghostfiles',71,'The Coming Terror! The Gate Of The Devil World!','24:00',1440,'https://media.kitsu.app/episode/9437/thumbnail/medium-a3b0dbcb8cd5a6bc085f6c6841868902.jpeg','Genkai and Koenma explain the new threat: someone wants to open the tunnel to Makai. They explain that humans have spontaneously been acquiring powers as a result of the tunnel opening, causing chaos in the Living World.','[]','1994-01-29','9437');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#72','yu-yu-hakusho-ghostfiles',72,'The Messengers Of The Devil World: Seven Enemies!','24:00',1440,'https://media.kitsu.app/episode/168754/thumbnail/medium-abe52d9766b1f92a3a4d490a19245c88.jpeg','Murota, another psychic human with the ability to tap into peoples minds appears, and Yusuke attempts to recruit him. Yusuke defeats Murota, who agrees to find the person who wants to open the Makai tunnel.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1994-02-05','168754');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#73','yu-yu-hakusho-ghostfiles',73,'Quietly Come Closer Wizard Doctor','24:00',1440,'https://media.kitsu.app/episode/168762/thumbnail/medium-0bb8c9986355e52fd3731f8d172954fb.jpeg','While Kuwabara, Kurama, Kaito, and Botan survey the cave, Yusuke''s group goes to the hospital after Murota was injured by Sniper and runs afoul of Doctor, who creates a mysterious poison that incapacitates both Yana and Murota.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1318,"end":1421}]','1994-02-12','168762');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#74','yu-yu-hakusho-ghostfiles',74,'Destroy The Territory!','24:00',1440,'https://media.kitsu.app/episode/168768/thumbnail/medium-13e7c9815b98b3fc89d775025b2768d9.jpeg','Yusuke battles Doctor, and is forced to come to a decision whether to kill him to save the people in the hospital. Ultimately, Yusuke blasts Doctor outside of his territory, rendering him unconscious and resolving the situation.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1318,"end":1419}]','1994-02-19','168768');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#75','yu-yu-hakusho-ghostfiles',75,'Seaman: The Trap In The Rain','24:00',1440,'https://media.kitsu.app/episode/168771/thumbnail/medium-676f8f20a42f2a6542e76b8f6702de7b.jpeg','After Kuwabara and friends attend a concert, they run afoul of Seaman. While Seaman traps Kuwabara''s friends inside his aquatic creature, Kuwabara''s inability to use his powers force him into a critical situation. Meanwhile, Kurama goes to see Koenma, as he suspects that Koenma may already know the identity of who is behind the plot to destroy the barrier.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1320,"end":1419}]','1994-02-26','168771');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#76','yu-yu-hakusho-ghostfiles',76,'Kuwabara Comes Back? Awakened Power','24:00',1440,'https://media.kitsu.app/episode/168784/thumbnail/medium-ffe812be5d605916a8a514dac00e6f27.jpeg','Kuwabara and Seaman continue their fight as Kuwabara''s dormant powers awaken, and Seaman realizes that Kuwabara can shatter barriers between different dimensions. Using his new spirit sword, Kuwabara frees his friends and defeats Seaman.','[]','1994-03-05','168784');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#77','yu-yu-hakusho-ghostfiles',77,'The Dark Past Of The Soul World Detective!','24:00',1440,'https://media.kitsu.app/episode/168789/thumbnail/medium-053320fc9e29b4b1a50b87010d40533b.jpeg','Yusuke learns the dark secret behind Sensui''s traumatic fall from Spirit Detective to the one who would wipe out all humanity.','[{"kind":"intro","label":"Opening","start":0,"end":110},{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1994-03-12','168789');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#78','yu-yu-hakusho-ghostfiles',78,'Attack! Black Angel','24:00',1440,'https://media.kitsu.app/episode/168793/thumbnail/medium-38979b61eca62a1a44bbc562e440f01e.jpeg','Yusuke battles Sensui in the streets, being overwhelmed by his moves. Elsewhere, Botan and Seaman are constantly attacked by Sniper, who is relentlessly firing small objects against them, in which Shizuru is badly injured by a diverted attack orchestrated by Sensui. Yusuke, Kuwabara, and Kurama chase Sensui inside a building, fighting against him one by one, only to be equally matched. Sensui leaves as Sniper arrives, devising a scheme to kidnap Kuwabara.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1296,"end":1378}]','1994-03-19','168793');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#79','yu-yu-hakusho-ghostfiles',79,'Yusuke Enraged To Go! Save Kuwabara!','24:00',1440,'https://media.kitsu.app/episode/168798/thumbnail/medium-b916086770c542c53b90dce81a2d4d65.jpeg','Sensui travels away while Yusuke is forced to contend with Sniper. Genkai arrives to heal the harsh wounds of both Botan and Shizuru. Sniper eventually marks Yusuke with targets, enabling his projectiles to be sent without him even having to aim. Koenma and Genkai are informed by Seaman of Kuwabara''s potential ability to shatter barriers. Sniper sends hundreds of rock projectiles at Yusuke with pinpoint accuracy, putting the latter in a dangerous situation.','[{"kind":"intro","label":"Opening","start":1,"end":130},{"kind":"outro","label":"Ending","start":1303,"end":1421}]','1994-03-26','168798');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#80','yu-yu-hakusho-ghostfiles',80,'The Target Of Hakiriharame! Death Wrinkle Cross Spot!','24:00',1440,'https://media.kitsu.app/episode/168802/thumbnail/medium-d654ef35bf4559b08ba17ff449dc263f.jpeg','Sniper continues his battle against Yusuke, using a semi-trailer truck as a projectile, and is nearly victorious until Hiei arrives. In a swing of his sword, Hiei incapacitates him. Hiei later fights Yusuke, only to prove the point the motivation that harnesses spirit energy. Hiei decides to join in the group in an attempt to stop Sensui.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1337,"end":1418}]','1994-04-02','168802');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#81','yu-yu-hakusho-ghostfiles',81,'The Game World In The Cave','24:00',1440,'https://media.kitsu.app/episode/168807/thumbnail/medium-4aa6dfc90b5133e71fef772109d9dacf.jpeg','Yusuke, Kurama, Hiei, Genkai, Seaman, Yana, and Kaito face Game Master, a young boy and a stellar gamer whose territory lets him bring any video game to life.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-04-09','168807');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#82','yu-yu-hakusho-ghostfiles',82,'Game King, With The Scary Force!','24:00',1440,'https://media.kitsu.app/episode/168811/thumbnail/medium-5ac6591c4cb07b2ccfa1fc7b9aa6f208.jpeg','When Yusuke''s group shows their skill at the games, Game Master plays himself, handily defeating Kaito. Kurama steps forward for the group to challenge him.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-04-16','168811');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#83','yu-yu-hakusho-ghostfiles',83,'The Means Left! The Decision Of Kurama!','24:00',1440,'https://media.kitsu.app/episode/168816/thumbnail/medium-7be96e182be94e9e48351f422a0f7655.jpeg','Kurama and Game Master play a puzzle game. Kurama''s emotional control and intimidation result in Game Master losing the game, and his life in the process.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1332,"end":1421}]','1994-04-23','168816');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#84','yu-yu-hakusho-ghostfiles',84,'The Anger Of Kurama! Who Is The Man','24:00',1440,'https://media.kitsu.app/episode/168821/thumbnail/medium-18f1bb44d3304c3794ef0b71586544cc.jpeg','Kurama, still torn over the outcome of the game, attacks Gourmet, who is revealed to been taken over by the Elder Toguro. Kurama traps the Elder Toguro within the Sinning Tree, which forces him to hallucinate his worst fear for all eternity.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1345,"end":1421}]','1994-04-30','168821');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#85','yu-yu-hakusho-ghostfiles',85,'The Spy Of The Soul World: Fight With Fate!','24:00',1440,'https://media.kitsu.app/episode/168826/thumbnail/medium-71f0185e0a02d25cdeba99a50b675b00.jpeg','Yusuke''s group finally reach Sensui. While Seaman, Kuwabara, Kurama, and Hiei are placed into another dimension by Gatekeeper, Yusuke must face Sensui alone. Sensui''s experience and long-trained abilities as a Spirit Detective put Yusuke at a disadvantage.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1334,"end":1417}]','1994-05-07','168826');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#86','yu-yu-hakusho-ghostfiles',86,'Yusuke Fight Hard, The Determined Difference','24:00',1440,'https://media.kitsu.app/episode/168831/thumbnail/medium-7852f4e54c9b84f4ae9f7cf3ba16295b.jpeg','As Yusuke manages to gain the advantage through sheer determination, Sensui switches personalities to Kazuya, a merciless killer. As Yusuke is about to lose his life, Koenma appears.','[{"kind":"intro","label":"Opening","start":0,"end":110},{"kind":"outro","label":"Ending","start":1319,"end":1421}]','1994-05-14','168831');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#87','yu-yu-hakusho-ghostfiles',87,'The King Of The Hell Junior Conscious Ring','24:00',1440,'https://media.kitsu.app/episode/168835/thumbnail/medium-f7debc009fb28fd52f708f60526343fd.jpeg','Koenma threatens Sensui with his Mafuukan, a defensive spell that can trap even S-class demons. Yusuke stops Koenma and handily defeats Kazuya; Shinobu, the primary personality, takes control of Sensui''s body.','[{"kind":"intro","label":"Opening","start":3,"end":93},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-05-21','168835');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#88','yu-yu-hakusho-ghostfiles',88,'Sensui: Be Careful With The Moral Light','24:00',1440,'https://media.kitsu.app/episode/168842/thumbnail/medium-3de90e1f737c29617c95be838086bb1d.jpeg','Sensui reveals his Sacred Energy, which places him on par with S-class demons. To stop him, Koenma releases the Mafuukan, but Sensui''s power enables him to break the Mafuukan, making the situation seem hopeless.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-05-28','168842');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#89','yu-yu-hakusho-ghostfiles',89,'When Everything Stops!','24:00',1440,'https://media.kitsu.app/episode/168849/thumbnail/medium-edbf28c60fb08f2fd258b6a3272a87d2.jpeg','Yusuke fares poorly against Sensui''s Sacred Energy, while his allies desperately attempt to break through Gatekeeper''s dimension. As Kuwabara manages to do so, Yusuke is struck down by Sensui.','[{"kind":"intro","label":"Opening","start":0,"end":100},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-06-04','168849');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#90','yu-yu-hakusho-ghostfiles',90,'Continued To Fulfill Our Friend''s Wish!','24:00',1440,'https://media.kitsu.app/episode/168855/thumbnail/medium-f68ef67e18abe948538f521fa3d71d64.jpeg','Incensed by the death of Yusuke, Kuwabara, Kurama, and Hiei increase their power and pursue Sensui through the tunnel. Kurama transforms into Yoko Kurama, as Hiei releases the Dragon of the Darkness Flame. Finally, Kuwabara slices through the barrier between worlds to pursue Sensui into Makai.','[{"kind":"intro","label":"Opening","start":9,"end":99},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-06-11','168855');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#91','yu-yu-hakusho-ghostfiles',91,'The Wakening Time! The Fight Continues!','24:00',1440,'https://media.kitsu.app/episode/168859/thumbnail/medium-3b455661aa449e90d88d74249bac9318.jpeg','The Special Defense Force is dispatched from the Spirit World to seal the breach. They are also ordered to terminate Yusuke, for he is a genetically inherited half-demon Mazoku species. However, Yusuke discovers his Mazoku nature and awakens. Pu is transported to the lair and transformed into a large blue phoenix. Then, Yusuke and Koenma enter into the breach, making their way toward Sensui and the rest of Yusuke''s friends.','[{"kind":"intro","label":"Opening","start":0,"end":100},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-06-18','168859');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#92','yu-yu-hakusho-ghostfiles',92,'The Proof That The Devil Nation Exists','24:00',1440,'https://media.kitsu.app/episode/168865/thumbnail/medium-78df5ed77563ed274efddbcf715c2df4.jpeg','A newly-revived Yusuke resumes his battle with Sensui. Kuwabara, Kurama, Hiei, and Koenma watch as Yusuke collides with Sensui, demon energy versus sacred energy. Nonetheless, Yusuke''s body is taken over by a mysterious force, fully awakening his demon side.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-06-25','168865');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#93','yu-yu-hakusho-ghostfiles',93,'Final Battle! The Final Battle In The Devil World!','24:00',1440,'https://media.kitsu.app/episode/168870/thumbnail/medium-2e2f7805a34744d30f549e7587445ef7.jpeg','Yusuke''s body has undergone an intense transformation as his latent demon blood takes hold. As the battle against Sensui concludes, Koenma tells Yusuke that he must choose between the Demon World and the Human World.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-07-02','168870');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#94','yu-yu-hakusho-ghostfiles',94,'Over! Run To Tomorrow!','24:00',1440,'https://media.kitsu.app/episode/168875/thumbnail/medium-41cd023c93bdab3958b4019678f31ffa.jpeg','Yusuke and his friends return to the surface to the arms of their friends. But all is not well. The Special Defense Force of Great King Enma arrive saying that they must destroy Yusuke once and for all. Could this be the end? How much energy does the Spirit Detective has after his exhausting battle with Sensui?','[{"kind":"intro","label":"Opening","start":1,"end":91},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-07-09','168875');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#95','yu-yu-hakusho-ghostfiles',95,'The Fate Of Yusuke''s Dangerous Relationship!','24:00',1440,'https://media.kitsu.app/episode/168878/thumbnail/medium-7d2589ed13a2ca16be4227bdb37805a6.jpeg','Yusuke Urameshi suffers from a recurring nightmare that he cannot shake. Is this a mere inconvenience? Or are there deeper meanings hidden behind the strange happenings? Genkai sends Yusuke to the home of a former spirit detective. But what he doesn''t know is that someone knows his fate... and more about his past than he ever thought possible!','[{"kind":"intro","label":"Opening","start":0,"end":100},{"kind":"outro","label":"Ending","start":1303,"end":1422}]','1994-07-16','168878');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#96','yu-yu-hakusho-ghostfiles',96,'Midnight Visitor: Deep Mystery','24:00',1440,'https://media.kitsu.app/episode/168885/thumbnail/medium-8dbb75e2b5acc2322baf00db6613f692.jpeg','The three men reveal they are present on the behalf of Raizen, one of the three kings of the Demon World. These three kings have been on a debate concerning the feasting of human bodies for over half a millennium. Yusuke tests his strength and agility against one of the men, Hokushin, who has the ability of elasticity. Upon defeat, Yusuke punches him back for not telling the whole story about the three kings.','[{"kind":"intro","label":"Opening","start":4,"end":94},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-07-23','168885');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#97','yu-yu-hakusho-ghostfiles',97,'Apart :The Way Of Each!','24:00',1440,'https://media.kitsu.app/episode/168892/thumbnail/medium-9cb516c97224d4ceca735e614b55f6ae.jpeg','After the three men leave, Kuroko tells Yusuke to leave as well. Kurama and Hiei have received invitations from the other two kings, Yomi and Mukuro, respectively. As Yusuke ponders on whether to accept Raizen''s invitation, he says his final farewell to Keiko Yukimura, saying he will return on his 18th birthday.','[{"kind":"intro","label":"Opening","start":5,"end":95},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-07-30','168892');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#98','yu-yu-hakusho-ghostfiles',98,'Go To The Devil World And Face The Father','24:00',1440,'https://media.kitsu.app/episode/168896/thumbnail/medium-60813513d60f95c3ad96fba09e8e0dde.jpeg','Kazuma Kuwabara receives the news that Yusuke, Kurama, and Hiei are on their way toward the Demon World. The three men escort Yusuke into the fortress of Raizen. Yusuke, incensed at Raizen''s interference in his fight with Shinobu "Black Angel" Sensui, encounters and attacks him, but is easily defeated. Raizen then begins to train Yusuke as his successor.','[{"kind":"outro","label":"Ending","start":1318,"end":1421}]','1994-08-06','168896');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#99','yu-yu-hakusho-ghostfiles',99,'Memory Which Can''t Be Forgotten! The Matter When Born!','24:00',1440,'https://media.kitsu.app/episode/168901/thumbnail/medium-54022772d7615bf69d9359a826fc237f.jpeg','Hiei undergoes the harsh training of Mukuro, being pushed to his own physical and emotional limits. He recounts to when he was born, sent into exile for being a curse to his village as a fire demon. Mukuro later brings Shigure, the surgeon that implanted the Jagan eye, to fight Hiei, for the reward of seeing Mukuro unmasked.','[{"kind":"intro","label":"Opening","start":0,"end":91},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-08-13','168901');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#100','yu-yu-hakusho-ghostfiles',100,'See The Light Again - The Secret Of Devil Eye','24:00',1440,'https://media.kitsu.app/episode/168905/thumbnail/medium-e5f0da0941bd3369c32db718748fbe55.jpeg','Hiei ponders his past of how he was raised by a group of bandits after being exiled. He recalls to when Shigure implanted the Jagan eye on his forehead as well as to when he trained with Shigure. Back to the present, he and Shigure simultaneously deal fatal blows to each other. Hiei thinks back to when he returned to the village in learning the aftermath of his banishment. Mukuro heals Hiei and reveals her true form as her sign of trust in him.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-08-20','168905');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#101','yu-yu-hakusho-ghostfiles',101,'Thieves Of The Devil World! The Thousand Years Meeting!','24:00',1440,'https://media.kitsu.app/episode/168908/thumbnail/medium-765c43e40dc786aa7aa2bdd8bcc79d4f.jpeg','Kurama travels to the territory of Yomi, Kurama''s former second-in-command. Yomi forces Kurama to serve him under threat of killing his human mother.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-08-27','168908');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#102','yu-yu-hakusho-ghostfiles',102,'Devil Fox Change! Hidden Sense Of Killing!','24:00',1440,'https://media.kitsu.app/episode/168915/thumbnail/medium-23ac9786467243c7134734f95e938154.jpeg','As Kurama mulls over Yomi''s offer, he goes back to the Living World to gather allies for Yomi, those who survived the Dark Tournament. After Shachi, one of Yomi''s subordinates, attacks him, Kurama transforms into Yoko Kurama, with his demon side seemingly dominating his personality.','[{"kind":"intro","label":"Opening","start":1,"end":91},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-09-03','168915');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#103','yu-yu-hakusho-ghostfiles',103,'The Words Left By Dad: The Old Memories','24:00',1440,'https://media.kitsu.app/episode/168917/thumbnail/medium-b9e9c02dcf3b3c117a2a2d7305fc0c18.jpeg','As Raizen is on death''s doorstep, he tells Yusuke the story of his lineage. Raizen dies, and Yusuke is left to find a way to stop total war from taking place in Demon World.','[{"kind":"intro","label":"Opening","start":0,"end":90}]','1994-09-10','168917');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#104','yu-yu-hakusho-ghostfiles',104,'Accidental Proposition: Change Of Devil World','24:00',1440,'https://media.kitsu.app/episode/168918/thumbnail/medium-7745cabd63818b4e54238b0b4e2aa130.jpeg','Due to Raizen''s demise, Mukuro intends to attack Yomi with full force. To avert the situation, Yusuke Urameshi offers an alternative to war, being a tournament whose winner will be crowned the king of Demon World. Raizen''s Friends visit his tombstone, and all of them power up at full strength to honor Raizen. With this in mind, Yomi finally decides to free his subordinates and his kingdom in order fight for himself. Then, in the following hundred days, the whole of Demon World was getting prepared. Yusuke and all the fighters are also getting ready to fight in the upcoming tournament to honor Raizen.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-09-17','168918');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#105','yu-yu-hakusho-ghostfiles',105,'The Devil Contest! The Beginning Of The Pre-Contest!','24:00',1440,'https://media.kitsu.app/episode/168919/thumbnail/medium-ecb378126a72f145df998051e9f18def.jpeg','Yusuke arrives for the competition, meeting Kurama, Hiei, Yomi, Mukuro, and a host of former competitors from the Dark Tournament. In the preliminary matches, the aforementioned combatants easily advance.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-09-24','168919');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#106','yu-yu-hakusho-ghostfiles',106,'The Battle Between Father And Son!','24:00',1440,'https://media.kitsu.app/episode/168921/thumbnail/medium-22597689a1abd6ad6f2b8f8b62500891.jpeg','Yomi battles his son, Shura, in the preliminaries, and his overwhelming power coerces Shura to eventually concede.','[{"kind":"intro","label":"Opening","start":5,"end":95},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-10-01','168921');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#107','yu-yu-hakusho-ghostfiles',107,'Fierce Fight! A Man Bets By Dream!','24:00',1440,'https://media.kitsu.app/episode/168922/thumbnail/medium-fc8beb8b003fccffe18c9b233bf96ca8.jpeg','Now, the Final Tournament starts. The initial matches continue their way, with many of the Dark Tournament combatants finding their match in Raizen''s Friends who are all S Class demon martial artists that joined the tournament.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-10-08','168922');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#108','yu-yu-hakusho-ghostfiles',108,'Hiei: Farewell With The Past!','24:00',1440,'https://media.kitsu.app/episode/168926/thumbnail/medium-bf23b4a590bf7b595c660fb3bc1e38cf.jpeg','Kurama battles Shigure, and is torn over his conflicting identities. Finally determining that he will live as a human, Kurama dispatches Shigure with his full power.','[{"kind":"intro","label":"Opening","start":0,"end":90},{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-10-15','168926');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#109','yu-yu-hakusho-ghostfiles',109,'Big Battle! Kurama And Mukuro!','24:00',1440,'https://media.kitsu.app/episode/168929/thumbnail/medium-14effaca74e35bfe4603d3b97d2f815a.jpeg','After seeing formidable encounters, it is now the turn of Hiei and Mukuro. Now, both of them engage into battle, each questioning the chains that each others'' past have left on them. As the battle concludes, Hiei is defeated, but manages to shatter Mukuro''s shackles in the process.','[{"kind":"outro","label":"Ending","start":1335,"end":1421}]','1994-10-22','168929');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#110','yu-yu-hakusho-ghostfiles',110,'This Is All My Power','24:00',1440,'https://media.kitsu.app/episode/168931/thumbnail/medium-c99778b61e0cc999400f9db69f7d4c10.jpeg','Yusuke battles Yomi, who is incensed that Yusuke suddenly finds no reason for fighting. Realizing that he must fight for the sake of his friends, Yusuke calls upon all his power to battle Yomi.','[{"kind":"intro","label":"Opening","start":1,"end":91}]','1994-10-29','168931');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#111','yu-yu-hakusho-ghostfiles',111,'The Final Decision','24:00',1440,'https://media.kitsu.app/episode/168933/thumbnail/medium-5a994961425cd3bee52a6e3c843ded57.jpeg','As the two combatants release all their power, they simultaneously hit each other, with Yusuke being rendered unconscious and Yomi barely remaining standing. Ultimately, a weakened Yomi proves unable to win the tournament, and Enki, one of Raizen''s friends, becomes the ruler of the Demon World, and institutes an era of peace for three years. Yusuke prepares to leave for the Living World, hoping to come back to the Demon World sometime soon.','[{"kind":"intro","label":"Opening","start":2,"end":92}]','1994-11-05','168933');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('yu-yu-hakusho-ghostfiles#112','yu-yu-hakusho-ghostfiles',112,'Forever Yu Yu Hakusho','24:00',1440,'https://media.kitsu.app/episode/168935/thumbnail/medium-b81a90938f545a5b7ad829657dc9c61b.jpeg','Two years after the tournament, Yusuke''s friends have found peace in their lives. They all decide to go to the beach, where Keiko yells for Yusuke at the beach. Yusuke suddenly appears, and is tackled by Keiko, who kisses him.','[]','1994-11-12','168935');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#1','ergo-proxy',1,'Awakening','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15220/original.jpg','When a series of mysterious attacks involving Cogito infected AutoReivs occur, Re-l is assigned to investigate, and encounters a humanoid monster. Later, she is attacked by two of these monsters at her home.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-02-25','15220');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#2','ergo-proxy',2,'Confession','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15221/original.jpg','Re-l struggles to convince her peers of her encounters with the monsters, which she learns are called Proxy. She is removed from the investigation and finds that Iggy has had his memories of recent events erased. Meanwhile, Vincent finds himself on the run from a proxy and then the city''s authorities.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-03-04','15221');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#3','ergo-proxy',3,'Mazecity','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15222/original.jpg','Romdo is no longer a safe haven for Vincent. He is trying to avoid capture by the authorities. As he flees he comes across the infected AutoReiv Pino. Pino then shows him the way to escape from Romdo to the outside world. Re-l struggles to contact Vincent and uncover the true nature of his involvement with the Proxy.','[{"kind":"outro","label":"Ending","start":1435,"end":1500}]','2006-03-11','15222');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#4','ergo-proxy',4,'Futu-Risk','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15223/original.jpg','Vincent and Pino are taken in by a small commune, the inhabitants of which make a living off the refuse dumped from the Dome. Meanwhile, Raul plans his move to locate and capture Vincent.','[{"kind":"outro","label":"Ending","start":1439,"end":1500}]','2006-03-18','15223');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#5','ergo-proxy',5,'Twilight','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15224/original.jpg','Re-l braves the outside world in order to bring Vincent back to Romdo. While there, Raul commences his plan to capture Vincent by attacking the Commune with patrol drones. Re-l''s environmental suit is damaged and Vincent is injured in the attack. Re-l suspicions are confirmed that there is a link between Vincent and the Proxies.','[{"kind":"outro","label":"Ending","start":1441,"end":1500}]','2006-04-01','15224');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#6','ergo-proxy',6,'Homecoming','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15225/original.jpg','Re-l''s life becomes endangered when she falls ill after exposure to the harsh environment. Hoody hatches a cunning plan to trick Raul and return to Romdo. Quinn leads a group on an escape from the Commune using the Rabbit.','[{"kind":"intro","label":"Opening","start":91,"end":181},{"kind":"outro","label":"Ending","start":1441,"end":1500}]','2006-04-08','15225');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#7','ergo-proxy',7,'RE-L124C41+','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15226/original.jpg','Re-l recovers from her illness. Daedalus shows her the disturbing mechanisms responsible for the Dome''s continued survival. Vincent makes his way home, slowly losing his companions along the way, ending up alone with Pino. A group of infected AutoReivs is unleashed on Re-l, Iggy, and Daedalus. The episode ends with Daedalus filling out Re-l''s death certificate.','[{"kind":"intro","label":"Opening","start":98,"end":191},{"kind":"outro","label":"Ending","start":1438,"end":1500}]','2006-04-15','15226');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#8','ergo-proxy',8,'Shining Sign','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15227/original.jpg','Vincent and Pino stumbles onto war-torn Halos, where they are caught in a war between the dome''s human inhabitants and its autonomous AutoReivs.','[{"kind":"intro","label":"Opening","start":114,"end":218},{"kind":"outro","label":"Ending","start":1439,"end":1500}]','2006-04-22','15227');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#9','ergo-proxy',9,'Angel''s Share','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15228/original.jpg','Vincent is introduced to a man named Hauer, and learns some truths about Halos and Proxies, discovering a horrific revelation.','[{"kind":"outro","label":"Ending","start":1441,"end":1500}]','2006-04-29','15228');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#10','ergo-proxy',10,'Cytotropism','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15229/original.jpg','Disturbed by recent events, Raul questions the future of Romdo. Meanwhile, Re-l and Iggy explore a strange antiquated dome inhabited only by primitive AutoReivs.','[{"kind":"outro","label":"Ending","start":1439,"end":1500}]','2006-05-13','15229');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#11','ergo-proxy',11,'Anamnesis','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15230/original.jpg','Vincent finds a strange book store and an even stranger old man, where he discovers more about his true nature. Re-l and Iggy catch up on the Centzon (the Rabbit, the flying ship that Vincent travels by).','[{"kind":"outro","label":"Ending","start":1439,"end":1500}]','2006-05-20','15230');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#12','ergo-proxy',12,'Hideout','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15231/original.jpg','The group is confronted by a vagrant Proxy and its companion AutoReiv, and Re-l puts her new weapon to use.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-05-27','15231');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#13','ergo-proxy',13,'Wrong Way Home','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15232/original.jpg','An infected Iggy becomes enraged and kidnaps Re-l, setting out to kill Vincent. Re-l is again confronted by the homeless AutoReiv.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-06-03','15232');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#14','ergo-proxy',14,'Ophelia','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15233/original.jpg','While resting in a long-abandoned dome, strange occurrences take place and the trio''s lives are endangered.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-06-10','15233');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#15','ergo-proxy',15,'Who Wants to be in Jeopardy!','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15234/original.jpg','Finding himself in a bizarre live game show, Vincent''s trivia knowledge is put to the test as he battles for his life.','[{"kind":"outro","label":"Ending","start":1480,"end":1500}]','2006-06-17','15234');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#16','ergo-proxy',16,'Busy Doing Nothing','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15235/original.jpg','When winds die out, the trio are stranded aboard the Centzon and Re-l finds herself struggling to hold on to her sanity.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-06-24','15235');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#17','ergo-proxy',17,'Terra Incognita','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15236/original.jpg','Romdo is on high alert as they search for the fugitive Raul, who plans to activate a deadly weapon. Meanwhile, the trio discover strange humanoids living inside a toxic cave system.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-07-01','15236');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#18','ergo-proxy',18,'Life After God','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15237/original.jpg','The trio reach the devastated Mosko, Vincent''s home city, and find that the truths lead back to Romdo.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-07-08','15237');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#19','ergo-proxy',19,'Eternal Smile','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15238/original.jpg','Pino explores the mysterious Smile Land with the NaKaMa, and confronts the Creator of the city.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-07-15','15238');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#20','ergo-proxy',20,'Goodbye, Vincent','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15239/original.jpg','Vincent finds himself trapped within Re-l''s consciousness, and observes powerlessly as events unfold.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-07-22','15239');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#21','ergo-proxy',21,'Shampoo Planet','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15240/original.jpg','A Cogito outbreak spreads through Romdo and the city falls into chaos. Vincent incites the people to revolt, pushing them to hunt down and kill all AutoReivs.','[{"kind":"outro","label":"Ending","start":1440,"end":1500}]','2006-07-29','15240');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#22','ergo-proxy',22,'Bilbul','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15241/original.jpg','As the city continues to crumble, Vincent and Re-l encounter Proxy One. Raul is overcome with regret and despair, and sets out to find Pino.','[]','2006-08-05','15241');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('ergo-proxy#23','ergo-proxy',23,'Deus ex Machina','25:00',1500,'https://media.kitsu.app/episodes/thumbnails/15242/original.jpg','Pieces are played and revelations uncovered as the final fight commences. Monad makes her return and tries to convince Vincent to join her.','[]','2006-08-12','15242');
